import{_ as o,o as n,c as e,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const d=JSON.parse('{"title":"Authoring for Living Worlds: Tool-Constrained LLM Agents for Executable Multi-Actor Scenarios","description":"","frontmatter":{"title":"Authoring for Living Worlds: Tool-Constrained LLM Agents for Executable Multi-Actor Scenarios","arxiv":"2604.10383","date":"2026-04-11","authors":"Nicolae Cudlenco, Mihai Masala, Marius Leordeanu","categories":"cs.CV","topics":"智能体视频生成, 事件图, 世界模型","outline":[2,2]},"headers":[],"relativePath":"papers/2604.10383.md","filePath":"papers/2604.10383.md","lastUpdated":null}'),s={name:"papers/2604.10383.md"};function a(i,t,g,l,p,u){return n(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="authoring-for-living-worlds-tool-constrained-llm-agents-for-executable-multi-actor-scenarios" tabindex="-1">Authoring for Living Worlds: Tool-Constrained LLM Agents for Executable Multi-Actor Scenarios <a class="header-anchor" href="#authoring-for-living-worlds-tool-constrained-llm-agents-for-executable-multi-actor-scenarios" aria-label="Permalink to &quot;Authoring for Living Worlds: Tool-Constrained LLM Agents for Executable Multi-Actor Scenarios&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2604.10383" target="_blank" rel="noreferrer">2604.10383</a></td></tr><tr><td><strong>提交日期</strong></td><td>v1 2026-04-11，v3 修订于 2026-07-29（本文依据 <strong>html v3</strong> 全文撰写）</td></tr><tr><td><strong>作者</strong></td><td>Nicolae Cudlenco, Mihai Masala, Marius Leordeanu（罗马尼亚科学院数学研究所 / Büchi Labortechnik AG / 布加勒斯特理工大学）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>不让 LLM 直接写世界规格，而是把 30 多个校验过的工具架在一个有状态的模拟器后端上，Director 与 Scene Builder 只能在后端当前允许的动作里选，因而产出的事件图按构造即合法——旗舰模型走标准分阶段流水线 50 次 0 次可执行，廉价模型走工具受限路线 25 次成功 20 次。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">标题口径说明</p><p>教程正文把本条目引作 &quot;Agentic Video Generation: From Text to Executable Event Graphs via Tool-Constrained LLM Planning&quot;。经核对 arXiv abs 页与 html v3，该 ID 的实际标题是 <strong>Authoring for Living Worlds: Tool-Constrained LLM Agents for Executable Multi-Actor Scenarios</strong>。本页元信息以 arXiv 条目为准；教程侧的标注与实际条目不符，缺陷在教程侧，本页不做改写。同组的技术报告 GEST-Engine 是另一个 ID（<a href="/notes/papers/2607.12231">arXiv:2607.12231</a>），数据集 GTASA 是第三个（arXiv:2604.10385），三者不要混淆。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>这篇论文的起点不是&quot;如何生成更好看的视频&quot;，而是&quot;<strong>如何为一个活的 3D 世界写剧本</strong>&quot;。它建立在 GEST-Engine 这个显式世界模型之上：输入是一张 GEST（Graph of Events in Space and Time），节点是事件（由演员在特定地点、对多个实体执行的动作），边携带来自 Allen 区间代数的时间约束，另外还支持逻辑关系与语义关系两类边。引擎先校验这张图，然后通过 Multi Theft Auto 框架在 GTA San Andreas 里<strong>确定性地</strong>执行它。</p><p>那个世界不小：70 多个环境、733 个物体、2500 多个动画、312 个角色皮肤。输出不只是一段片子，而是&quot;片子加上它背后的世界&quot;：2 到 6 个同步的演员在自动跟拍下演完一个多场景故事，引擎逐帧记录实体与相机状态、所有成对空间关系、实例分割、精确的事件到帧的边界，以及一段由图导出的文本描述。</p><p>为什么值得做：在 GTASA 语料上，16 位标注者判定引擎视频的物理合理性为 <strong>69%</strong>，而 VEO 3.1 是 18%、WAN 2.2 是 13%；与给定故事的语义匹配度为 <strong>4.09/5</strong>，对照两者是 2.50 和 1.75。但迄今为止引擎跑的都是<strong>随机生成的图</strong>。本文补上的是创作环节：让 LLM agent 把自由文本变成完整的可执行规格——演职人员、地点、每个演员的动作链及其同步与时序约束，而且这个世界里每一个动作都会改变状态。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>LLM 编排的视频生成流水线</strong>：StoryAgent、MAViS、DreamRunner 把编剧、选角、渲染分派给专门 agent；VideoDirectorGPT、Dysen-VDM 用 LLM 构建的计划去条件化 diffusion。论文对这一整类的批评很尖锐：最终拍板的是神经生成器，物体会凭空出现和消失、演员会形变、时序会崩，而且<strong>没有任何计划层的产物在生成后留存下来</strong>，因此输出根本无从校验。这些工作没有一篇报告可执行率——在它们的设定里这个概念不存在。</p><p><strong>Agent 驱动引擎</strong>：GPT4Motion 让 LLM 写 Blender 脚本做物理引导生成，但只能指挥三种基本运动 primitive。FilmAgent 在 Unity 里做多智能体电影制作，从预定义的走位、动作、镜头里挑——论文的评价是&quot;它的世界是一份菜单：可枚举、无状态、每个选择都合法，所以在那里根本问不出可执行性这个问题&quot;。同期的 Cutscene Agent 通过工具创作 Unreal 过场，并用 API 导出的依赖图检查调用轨迹，但那是<strong>轨迹合法性</strong>而非<strong>世界状态合法性</strong>，且没有 baseline 对比与消融。</p><p><strong>合成数据传统</strong>：从 Playing for Data 到 BEDLAM、VirtualHome、Action Genome，早就证明了模拟能带来规模化的完美标注。但在这些平台上，规格都是研究者手写或用代码写的。</p><p><strong>已有的 text-to-GEST 原型</strong>在原理上演示过这个转换，但没有以可执行性为目标。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>作者说得很直白：他们先造了最直接的那个系统。用 LangGraph 搭一条六阶段流水线（Concept → Casting → Episode Placement → Setup → Screenplay → Scene Detail），驱动当时的旗舰模型 GPT-5，每阶段都要求结构化输出并解析，失败最多重试三次。跑 50 个故事。</p><p>结果是：叙事连贯、有逻辑结构、有人物动机，<strong>0 个可执行</strong>。45 个产出了完整的图，剩下 5 个在细化阶段就卡死了。引擎一个也放不进去，因为它们要求的场景没有任何一个 episode 能承载。</p><p>失败模式非常具体，值得逐条抄下来，因为它们解释了为什么这个问题不能靠 prompt 工程解决：<strong>近似动作 id</strong>（写成 &quot;LookAtWatch&quot;，而世界里叫 &quot;LookAtTheWatch&quot;，45 个里有 8 个）；<strong>状态规则违反</strong>（演员没站起来就又坐下了，45 个里有 21 个）；<strong>不可能的放置</strong>（在客厅里要求一串笔记本电脑动作链，而世界不在客厅放笔记本）；<strong>物体生命周期违反</strong>（放下从没拿起过的东西，45 个里有 5 个）；以及<strong>规则无视</strong>——每个阶段都收到了从 14000 行能力注册表里精心切出来的一片（Scene Detail 的 prompt 大约有 3800 行规则、时序关系、参考图和 episode 数据），模型仍然违反<strong>逐字写在它上下文里</strong>的规则。</p><p>这两类失败对应世界难写的两个性质：注册表永远无法完整放进上下文；合法性是<strong>状态条件</strong>的。每个阶段做的都是局部合理的决定，但累积状态（谁在哪、拿着什么、哪个 POI 被占了、哪些约束生效）随着 GEST 变大而漂离合法域。而且事后修不好：没有固定的归一化能覆盖非确定性的幻觉，修好一处违规会让后续事件依赖的状态失效，于是修正的回溯代价是超线性的。</p><p>结论只能是：<strong>合法性必须在规格被写下的地方强制，而不是写完之后检查。</strong></p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把决策权拆开：LLM 决定<strong>应该发生什么</strong>，一个程序化的状态后端决定<strong>什么被允许发生</strong>。agent 不再&quot;知道&quot;规则并试图遵守，它只能从后端在当前状态下返回的合法延续里挑一个。规格因此按构造即合法，幻觉出来的动作 id 根本没有机会被写进图里。一旦约束搬进工具层，模型能力就不再是瓶颈——廉价模型足够了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>系统建在 LangGraph 的 deepagents 上：ReAct 式的反应型 agent，通过层级化的 subagent 委派组织，全部由 <strong>Claude Haiku 4.5</strong>（当时该供应商的廉价档）驱动。</p><p><strong>Director Agent</strong> 接收可选的 seed text 与生成配置，分四个阶段工作：</p><ul><li><strong>Exploration</strong>：用只读工具把 14000 行能力注册表分页读小块（episodes、regions、POI 动作链、带视觉描述的角色皮肤）。这个 explore-before-plan 模式是防幻觉的关键——<strong>一个动作只有在某次工具调用确认它存在之后，才能进入计划</strong>。</li><li><strong>Casting</strong>：创建故事与演员（姓名、性别、皮肤、起始 region）。</li><li><strong>Scene building</strong>：顺序处理场景。每个场景选定 episode、region、参与者，用一段自然语言 brief 委派给 Scene Builder，事后把演员在 region 之间移动。</li><li><strong>Finalization</strong>：用跨场景的时序约束把各场景的边界连起来。</li></ul><p><strong>Scene Builder Subagent</strong> 拿到的是隔离的上下文（场景、episode、region、演员、brief），<strong>从不看故事的其余部分</strong>。它用一个基于轮次的状态机构造事件：一轮开始时给出每个演员的当前状态（姿态、手持物、位置）；对每个演员，subagent 在某个 POI 上起一条链，然后在后端返回的合法延续里往下延伸。举例：一个演员在有笔记本的桌前坐下，就为其他所有人占用了那个座位，接下来他可以打开笔记本或站起来；打开笔记本后，&quot;在上面打字&quot;和&quot;合上它&quot;成为新的延续项。双人同步交互、相机控制、跨演员时序依赖都是各自独立的、经过校验的调用。关闭一轮时提交跨演员的排序。链是<strong>原子提交</strong>的：事件先进缓冲区，只有显式 commit 才写进 GEST，失败的探索不留痕迹。</p><p>每个场景之后与最终组装之后，Director 可以再委派两个 subagent：<strong>Logical Relations Agent</strong> 加因果与依赖边（causes / enables / prevents / requires），<strong>Semantic Relations Agent</strong> 加自由文本类型的叙事连贯边（observes / interrupts / motivates）。这两类边对执行是可选的，但它们填上了 GEST 形式化里<strong>程序化生成永远不会产生</strong>的那部分表达力。论文示例故事 &quot;An Evening of Connection&quot; 里是 13 条语义边、29 条逻辑边。</p><p><strong>状态后端</strong>是整套设计的地基：引擎自带的程序化随机生成器，扩展出一个委派接口，把它的操作暴露成 30 多个校验过的工具。工具实现了一个基于事务的状态机，跨 IDLE / STORY_CREATED / IN_SCENE / IN_ROUND 四个状态。后端强制独占物体的 POI 容量；在接受任何 <code>before</code> 关系前先走一遍依赖图，拒绝会造成环的边；协调双人交互（同地点、姿态、以及 Give 必须有显式接收者并自动同步一个接收事件）；锁定原子物体序列（如 TakeOut → Use → Stash）直到完成。<strong>拒绝时返回可解释的错误，agent 用它重新规划</strong>——这就是 agent 视角下的环境动力学。</p><p>代价方面：约束住在工具里，廉价模型就够用，一个完整的多场景故事大约花 <strong>$0.25</strong> 的 API 调用。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>语料与协议</strong>。评测在 GTASA 上进行，故事在场景类型（教室、健身房、花园、住宅、混合）与演员数（2–6）上有多样性，每条自带 GEST、执行视频与文本描述。描述的生成方式是：先把图转成一种 proto-language，再让 LLM 润色成自然语言，<strong>不改动演员、事件与动作顺序</strong>。选 25 条语料故事，把描述当作 seed text 交给 Director。加上分阶段 baseline，端到端评了 75 次创作尝试。</p><p>选择从语料播种而不是手写故事，是为了让两件事可测：一是可执行性，二是<strong>重建保真度</strong>——因为 seed text 背后有一张源图可以对照。</p><p><strong>结论一：约束住哪里决定一切。</strong> 表 1：分阶段流水线 50 次尝试，0 次执行成功（0%）；工具受限 agent 25 次尝试，20 次成功（<strong>80%</strong>）。作者的论证很干净：赢的那一方跑的是更弱的模型，所以差距不可能是模型效应；变的是约束存放的位置——是作为指令写在 prompt 里，还是作为任何输出都绕不过的检查写在工具层。</p><p>agent 那 5 次失败<strong>也不是约束违反</strong>：它的图按构造即合法，五次都被引擎接收了，然后在运行时崩溃或卡住直到模拟重试用尽——这与语料流水线报告的程序化生成器（同样是 valid-by-construction 的图）的引擎侧失败模式相同。</p><p><strong>结论二：故事能在 图 → 文本 → agent → 图 的往返里活下来。</strong> 表 2 的 F1（20 对，均值±标准差，右列是随机 baseline）：仅动作 <strong>0.85±0.15</strong>（随机 0.61±0.19）；动作+实体类型 <strong>0.83±0.18</strong>（0.55±0.21）；动作+实体+地点 <strong>0.63±0.39</strong>（0.35±0.30）；以每个演员的动作 bigram 计的时序结构 <strong>0.77±0.21</strong>（0.43±0.21）。随机 baseline 的构造是：每条源图对 3 条在场景类型与演员数上匹配的随机语料场景，20 对共 60 次比较。agent 在事件上 19/20、在时序结构上 20/20 胜过自己那一对的 baseline 均值（符号检验 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>）。</p><p><strong>结论三：残差正好落在语言通道丢失信息的地方。</strong> 4 对完全重建（各层级 F1 均为 1.0），并经核实是节点身份不同的真重建而非复制，说明当文本保住了信息时天花板是可达的。地点那一层解释了大部分残差：<strong>当 seed text 点名了 region，agent 就落在源 region；而五条教室文本从不点名 region，恰好就是地点得分为 0 的那五对。</strong></p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：为一个每个动作都改变状态的活世界写规格，需要同时满足叙事自由与模拟严格，而 LLM 只擅长前者。分阶段驱动旗舰模型的标准设计彻底失败：50 次 0 次可执行，失败原因是能力注册表放不进上下文、合法性是状态条件的，且错误无法事后修复（修一处会让后续依赖失效，回溯代价超线性）。可行的架构是分离关注点——LLM 决定应该发生什么，30 多个工具背后的事务型状态后端决定什么被允许发生，于是规格按构造即合法。廉价模型跑这套 25 次成功 20 次，单个多场景故事约 $0.25。因为 seed text 是从源图导出的，还能测重建：事件 F1 0.83（随机 0.55），时序结构 0.77（随机 0.43），残差集中在文本没点名地点的样本上。</p><p><strong>3 句话版</strong>：把约束从 prompt 搬进工具层，可执行率从 0/50 变成 20/25，而且赢的那边用的是更弱的模型。规格按构造即合法，agent 只能从后端当前允许的动作里选，幻觉的动作 id 没有机会写进图。剩下的失败全部来自引擎运行时，而非 agent 的决策。</p><p><strong>1 句话版</strong>：不要教模型遵守规则，让它只能做合法的事。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>&quot;按构造即合法&quot;等价于&quot;好&quot;。</strong></p><p>这套设计的强项恰恰造成了它的评测盲区。工具层保证了每一张产出的图都合法，因此可执行率的上限就是引擎运行时的可靠性，与 agent 讲故事的能力几乎无关——一个退化的 agent（让所有演员各自坐下再站起来）也会得到 100% 的可执行率。论文自己承认那 5 次失败&quot;不是约束违反&quot;，这等于承认可执行性这一项已经<strong>测不动 agent 的质量</strong>了。</p><p>真正衡量创作质量的只有重建保真度，而它只在<strong>有 seed 的运行</strong>上可测。论文强调的另一个能力——Director 通过自己探索世界来构思故事——完全没有对应的量化评价。同时，agent 产出的视频<strong>没有做过人评</strong>：69% 物理合理性与 4.09/5 语义匹配这两个数字来自 GTASA 语料，跑的是程序化生成的图；论文的表述是&quot;我们的 agent 驱动同一个执行器，所以我们的视频继承那些结果&quot;。这是<strong>继承性论断而非测量</strong>。继承成立的前提是 agent 写出的图与随机生成的图在分布上可比，但整篇论文的卖点恰恰是它写的图更有叙事结构、用上了程序化生成从不产生的逻辑边与语义边——两个论断互相拉扯。</p><p>还有一个数字值得盯住：随机 baseline 在&quot;仅动作&quot;这一层已经拿到 <strong>0.61</strong>。也就是说，随便挑一个场景类型与演员数相同的语料故事，它的动作集合就已经和目标重合六成。这是世界动作词表规模有限的直接后果。在这个基线之上，0.85 的意义比&quot;0.83 对 0.55&quot;这个对照读起来要小。论文没有报告一个更强的非 agent baseline，例如直接从 seed text 里抽取动词再匹配到最近的合法动作 id。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>目标是把&quot;工具层&quot;从&quot;层级架构 + 探索模式 + 换模型&quot;里剥离出来，因为论文的 0/50 与 20/25 之间同时变了四件事。</p><p>不需要 GTA 世界。用 VirtualHome 或任何带状态的家务模拟器即可，它同样有动作词表、物体生命周期与前置条件。</p><ul><li>定义可执行性：程序生成的动作序列能被模拟器无错执行。</li><li>准备 20 条自然语言任务描述。</li><li>跑四个配置，模型全部固定为同一个廉价模型：(a) 单轮 prompt，把完整动作词表与规则塞进上下文；(b) 分阶段流水线（分解 → 细化），仍然只有 prompt 约束；(c) 单个 agent + 校验工具层（工具只返回当前状态下的合法延续，非法调用返回解释性错误）；(d) 层级 Director/Builder + 同一套工具层。</li><li>测每个配置的可执行率、平均工具调用次数、以及被后端拒绝后成功重规划的比例。</li><li><strong>支持论文</strong>：(c) 相对 (a)(b) 有数量级的跃升，而 (d) 相对 (c) 提升有限——说明收益几乎全部来自工具层。<strong>反驳论文</strong>：(c) 与 (b) 接近而 (d) 明显更好，说明起作用的是层级分解与上下文隔离，&quot;约束住在哪里&quot;的叙事需要修正。</li></ul><p>这个实验一周内可做完，且完全不需要接触 GEST-Engine。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>论文的核心 claim 是&quot;约束的位置决定可执行性，模型能力不是瓶颈&quot;。它对模型混淆的辩护是&quot;赢的那边用的是更弱的模型&quot;，这个辩护只挡住了一个方向的解释，挡不住反方向：<strong>也许 Claude Haiku 4.5 恰好比 GPT-5 更擅长多轮工具调用与从错误中恢复</strong>，而这正是工具受限设定所要求的能力。分阶段设定考的是长上下文规则遵循，工具设定考的是 agentic 循环，两个模型在这两项上的强弱完全可能相反。</p><p>设计这样的反例：<strong>做 2×2</strong>。两个模型（旗舰 / 廉价）× 两种约束位置（prompt / 工具层），各跑 25 次。论文只填了对角线上的两格。如果补全后发现旗舰模型在工具层设定下也是 80% 左右、廉价模型在 prompt 设定下也是 0%，论文的 claim 成立且更强；如果旗舰模型在工具层下显著更高，说明&quot;廉价模型就够&quot;这条省钱结论过度外推。这个实验的成本约为 $12 的 API 费用加引擎时间，论文没有做。</p><p>另一条独立攻击针对&quot;世界是活的&quot;这个前提。论文批评 FilmAgent 的世界&quot;是一份菜单：可枚举、无状态、每个选择都合法&quot;。但工具层暴露给 agent 的接口——&quot;后端返回当前状态下的合法延续，你从中选一个&quot;——在每一步上<strong>恰好就是一份菜单</strong>，只不过这份菜单会随状态刷新。区别是量的（菜单随状态变化）而非质的。要证明这个区别真的重要，需要显示 agent 在<strong>跨越多个 POI 与多个演员的长程依赖</strong>上做出了非平凡的选择，而不只是在每一步局部合法的选项里挑。一个能证伪的测试：把后端改成每次只返回合法延续的一个随机子集（大小为 1），agent 完全丧失选择权，此时重建 F1 应当塌到随机 baseline 附近；如果它仍然接近 0.83，那么现在的分数主要由世界的可供性结构而非 agent 的规划决定。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：整套系统里，模拟器只会说&quot;不行&quot;。拒绝返回的是解释性错误，agent 用它重新规划，但这些拒绝<strong>没有被沉淀成任何可复用的东西</strong>——每个故事都从零开始探索 14000 行注册表，下一次遇到同样的死路还会再撞一次。这也是为什么可执行性一旦被工具层保证，就再也无法反映 agent 的学习。</p><p><strong>新 framing</strong>：把创作从&quot;单次的 agent-环境交互&quot;重构成<strong>世界可供性的增量学习问题</strong>。agent 每次探索都在给这个世界画一张更完整的地图：哪些动作链在哪些 POI 上可行、哪些组合会撞容量上限、哪些时序约束会成环。把这些沉淀成一个<strong>可检视的、可被后续 agent 继承的世界模型摘要</strong>，创作就从每次重新摸索变成在已知地图上做规划。更进一步，这张地图本身可以被评价：它对世界的覆盖率、它的预测准确率（预言某个操作会被拒绝，然后验证），这给出了一个<strong>不依赖可执行率</strong>的质量指标，正好补上 §9 指出的评测盲区。</p><p><strong>可借鉴的相邻工具</strong>：经典规划里的 action model learning（从执行轨迹里归纳 STRIPS 风格的前置条件与效果），以及强化学习里的 successor features / 可供性学习。这两者都假设可以廉价地试错，而模拟器恰好提供了这个条件。</p><p><strong>第一个实验</strong>：让 agent 在无 seed 的自由探索模式下跑 200 个故事，记录每一次工具拒绝与其错误信息，从中归纳出前置条件规则集。然后测两件事：(a) 用归纳出的规则集初始化一个新 agent，它的平均工具调用次数与单故事成本下降多少（当前基准是约 $0.25）；(b) 规则集对留出的 POI/动作组合的<strong>拒绝预测准确率</strong>——这是一个可以对照 ground truth（后端本身）计算的硬指标。如果准确率高，说明世界的可供性结构是可学的，那么&quot;探索&quot;这一阶段可以被摊销掉；如果低，说明这个世界的合法性本质上是不可压缩的组合关系，那么工具层不只是工程便利，而是<strong>必需品</strong>——这个结论会反过来把本文的架构主张从经验观察升级为原理性论断。</p>',61)])])}const h=o(s,[["render",a]]);export{d as __pageData,h as default};
